<template>
  <div class="payments-view">
    <NavBarVue />
    <b-container fluid>
      <div class="page-content">

        <!-- ===================== CABEÇALHO ===================== -->
        <div class="d-flex align-items-center mb-3">
          <div>
            <h5 class="mb-0 font-weight-bold text-dark">
              <b-icon icon="wallet2" class="mr-2 text-success"></b-icon>
              Pagamentos de Prestações
            </h5>
            <small class="text-muted">Listagem de todos os pagamentos efectuados</small>
          </div>
          <div class="ml-auto" v-if="pagination.totalItems > 0">
            <b-badge variant="success" pill class="px-3 py-2">
              {{ pagination.totalItems }} pagamento{{ pagination.totalItems !== 1 ? 's' : '' }}
            </b-badge>
          </div>
        </div>

        <!-- ===================== FILTROS ===================== -->
        <b-card class="filter-card mb-3" no-body>
          <b-card-body class="py-2 px-3">
            <b-row align-v="end">
              <b-col lg="2" md="4" sm="6" class="mb-2 mb-lg-0">
                <b-form-group label="Data Início" label-size="sm" class="mb-0">
                  <b-form-datepicker
                    placeholder="Data início"
                    block
                    size="sm"
                    id="pay-from-datepicker"
                    v-model="fromDate"
                    :date-format-options="{ year: 'numeric', month: '2-digit', day: '2-digit' }"
                  ></b-form-datepicker>
                </b-form-group>
              </b-col>
              <b-col lg="2" md="4" sm="6" class="mb-2 mb-lg-0">
                <b-form-group label="Data Fim" label-size="sm" class="mb-0">
                  <b-form-datepicker
                    placeholder="Data fim"
                    block
                    size="sm"
                    id="pay-to-datepicker"
                    v-model="toDate"
                    :min="fromDate"
                    :date-format-options="{ year: 'numeric', month: '2-digit', day: '2-digit' }"
                  ></b-form-datepicker>
                </b-form-group>
              </b-col>
              <b-col lg="2" md="4" sm="6" class="mb-2 mb-lg-0">
                <b-form-group label="Meio de Pagamento" label-size="sm" class="mb-0">
                  <b-form-select
                    v-model="selectedPaymentMethod"
                    :options="paymentMethodOptions"
                    size="sm"
                  ></b-form-select>
                </b-form-group>
              </b-col>
              <b-col lg="2" md="4" sm="6" class="mb-2 mb-lg-0">
                <b-form-group label="Pesquisar" label-size="sm" class="mb-0">
                  <b-form-input
                    v-model="searchTerm"
                    size="sm"
                    placeholder="Nº conta, referência..."
                    @keyup.enter="fetchPayments(1)"
                  ></b-form-input>
                </b-form-group>
              </b-col>
              <b-col cols="auto" class="mb-2 mb-lg-0">
                <b-button
                  size="sm"
                  variant="success"
                  @click="fetchPayments(1)"
                  :disabled="loadingData"
                >
                  <b-icon icon="search" class="mr-1"></b-icon>
                  Buscar
                </b-button>
                <b-button
                  size="sm"
                  variant="outline-secondary"
                  class="ml-1"
                  @click="clearFilters()"
                  title="Limpar filtros"
                >
                  <b-icon icon="x-circle" class="mr-1"></b-icon>
                  Limpar
                </b-button>
              </b-col>
              <b-col class="text-right mb-2 mb-lg-0">
                <b-button
                  size="sm"
                  variant="outline-success"
                  class="mr-1"
                  @click="exportExcel()"
                  :disabled="payments.length === 0"
                  title="Exportar Excel"
                >
                  <b-icon icon="file-earmark-spreadsheet" class="mr-1"></b-icon>
                  Excel
                </b-button>
                <b-button
                  size="sm"
                  variant="outline-primary"
                  @click="exportPDF()"
                  :disabled="payments.length === 0"
                  title="Exportar PDF"
                >
                  <b-icon icon="printer-fill" class="mr-1"></b-icon>
                  PDF
                </b-button>
              </b-col>
            </b-row>
          </b-card-body>
        </b-card>

        <!-- ===================== RESUMO KPIs ===================== -->
        <b-card class="kpi-card mb-3" no-body v-if="payments.length > 0">
          <b-card-body class="py-2 px-3">
            <div class="kpi-strip">
              <div class="kpi-item">
                <span class="kpi-label">Total Pago</span>
                <span class="kpi-value text-success">{{ convertMoney(totals.totalAmount) }}</span>
              </div>
              <div class="kpi-item">
                <span class="kpi-label">Juros de Mora</span>
                <span class="kpi-value text-warning">{{ convertMoney(totals.totalLateInterest) }}</span>
              </div>
              <div class="kpi-item">
                <span class="kpi-label">Registos</span>
                <span class="kpi-value">{{ pagination.totalItems }}</span>
              </div>
              <div class="kpi-item">
                <span class="kpi-label">Período</span>
                <span class="kpi-value" style="font-size: 0.82rem">{{ getPeriodLabel() }}</span>
              </div>
            </div>
          </b-card-body>
        </b-card>

        <!-- ===================== TABELA DE PAGAMENTOS ===================== -->
        <b-card class="report-card mb-3" no-body>
          <b-card-header class="report-header">
            <b-icon icon="table" class="mr-2"></b-icon>
            Lista de Pagamentos
            <b-badge variant="light" pill class="ml-2 text-dark" v-if="payments.length > 0">
              {{ pagination.totalItems }}
            </b-badge>
            <span class="report-period ml-3" v-if="fromDate && toDate">{{ getPeriodLabel() }}</span>
          </b-card-header>
          <b-card-body class="p-0">
            <b-overlay :show="loadingData" rounded="sm">

              <div class="table-responsive" v-if="payments.length > 0">
                <table class="table table-sm table-hover table-bordered report-table mb-0">
                  <thead>
                    <tr class="table-header-row">
                      <th class="align-middle text-center" style="width: 40px">#</th>
                      <th class="align-middle">Nome do Cliente</th>
                      <th class="align-middle text-center">Nº Conta</th>
                      <th class="align-middle text-right">Valor Pago (MZN)</th>
                      <th class="align-middle text-center">Método</th>
                      <th class="align-middle text-center">Referência</th>
                      <th class="align-middle text-center">Data Pagamento</th>
                      <th class="align-middle">Técnico</th>
                      <th class="align-middle">Descrição</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr
                      v-for="(payment, idx) in payments"
                      :key="payment.id"
                      class="data-row"
                    >
                      <td class="text-center">{{ getRowIndex(idx) }}</td>
                      <td>{{ getCustomerName(payment.accountNumber) }}</td>
                      <td class="text-center">{{ payment.accountNumber }}</td>
                      <td class="text-right font-weight-bold text-success">{{ convertMoney(payment.amount) }}</td>
                      <td class="text-center">
                        <b-badge :variant="getMethodVariant(payment.paymentMethod)" pill>
                          {{ getPaymentMethod(payment.paymentMethod) }}
                        </b-badge>
                      </td>
                      <td class="text-center">{{ payment.tranzactionReference }}</td>
                      <td class="text-center" v-date-format="payment.paymentDate || payment.createdAt"></td>
                      <td>{{ payment.staffName }}</td>
                      <td class="text-truncate" style="max-width: 150px" :title="payment.description">
                        {{ payment.description }}
                      </td>
                    </tr>
                  </tbody>
                  <tfoot v-if="payments.length > 0">
                    <tr class="totals-row">
                      <td colspan="3" class="text-right font-weight-bold">Totais da Página</td>
                      <td class="text-right font-weight-bold">{{ convertMoney(getPageTotalAmount()) }}</td>
                      <td colspan="5"></td>
                    </tr>
                  </tfoot>
                </table>
              </div>

              <!-- Sem dados -->
              <b-alert
                class="text-center m-3"
                v-if="payments.length === 0 && !loadingData"
                variant="info"
                show
              >
                <b-icon icon="search" class="mr-1"></b-icon>
                Seleccione um intervalo de datas e clique em "Buscar" para listar os pagamentos.
              </b-alert>

            </b-overlay>
          </b-card-body>

          <!-- ===================== PAGINAÇÃO ===================== -->
          <b-card-footer class="py-2 px-3" v-if="payments.length > 0">
            <div class="d-flex align-items-center justify-content-between flex-wrap">
              <small class="text-muted mb-2 mb-md-0">
                A mostrar {{ getShowingFrom() }}-{{ getShowingTo() }} de {{ pagination.totalItems }} registos
                | Página {{ pagination.currentPage }} de {{ pagination.totalPages }}
              </small>
              <div class="d-flex align-items-center">
                <b-button-group size="sm">
                  <b-button
                    variant="outline-secondary"
                    :disabled="pagination.currentPage <= 1"
                    @click="fetchPayments(1)"
                    title="Primeira página"
                  >
                    <b-icon icon="chevron-bar-left"></b-icon>
                  </b-button>
                  <b-button
                    variant="outline-secondary"
                    :disabled="pagination.currentPage <= 1"
                    @click="fetchPayments(pagination.currentPage - 1)"
                    title="Página anterior"
                  >
                    <b-icon icon="chevron-left"></b-icon>
                  </b-button>
                </b-button-group>
                <span class="mx-2 font-weight-bold" style="font-size: 0.82rem">
                  {{ pagination.currentPage }} / {{ pagination.totalPages }}
                </span>
                <b-button-group size="sm">
                  <b-button
                    variant="outline-secondary"
                    :disabled="pagination.currentPage >= pagination.totalPages"
                    @click="fetchPayments(pagination.currentPage + 1)"
                    title="Próxima página"
                  >
                    <b-icon icon="chevron-right"></b-icon>
                  </b-button>
                  <b-button
                    variant="outline-secondary"
                    :disabled="pagination.currentPage >= pagination.totalPages"
                    @click="fetchPayments(pagination.totalPages)"
                    title="Última página"
                  >
                    <b-icon icon="chevron-bar-right"></b-icon>
                  </b-button>
                </b-button-group>
              </div>
            </div>
          </b-card-footer>
        </b-card>

      </div>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import moment from "moment";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import DateFormat from "@/utils/dateFormat";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;
import * as XLSX from "xlsx";

export default {
  data: () => ({
    fromDate: moment().startOf("month").format("YYYY-MM-DD"),
    toDate: moment().format("YYYY-MM-DD"),
    searchTerm: "",
    selectedPaymentMethod: 0,

    paymentMethodOptions: [
      { value: 0, text: "Todos" },
      { value: 1, text: "Boca de Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "SISTAFE" },
      { value: 7, text: "M-Pesa Open-Api" },
      { value: 8, text: "E-Mola" },
    ],

    payments: [],
    loadingData: false,
    currentPage: 1,
    perPage: 15,

    pagination: {
      currentPage: 1,
      totalPages: 1,
      totalItems: 0,
      itemsPerPage: 15,
      hasNextPage: false,
      hasPrevPage: false,
    },

    totals: {
      totalAmount: 0,
    },
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "customers",
      "company",
    ]),
  },

  watch: {
    company: {
      handler(val) {
        if (val && val.id && this.payments.length === 0) {
          this.fetchPayments(1);
        }
      },
      immediate: true,
    },
  },

  methods: {
    // ==================== BUSCAR DADOS ====================

    fetchPayments(page) {
      if (!this.company || !this.company.id) return;

      this.loadingData = true;
      this.currentPage = page;

      const params = new URLSearchParams();
      params.append("page", page);
      params.append("limit", this.perPage);

      if (this.fromDate) params.append("fromDate", this.fromDate);
      if (this.toDate) params.append("toDate", this.toDate);
      if (this.searchTerm) params.append("search", this.searchTerm);
      if (this.selectedPaymentMethod > 0) {
        params.append("paymentMethod", this.selectedPaymentMethod);
      }

      axios
        .get(`/api/payments/${this.company.id}/paginated?${params.toString()}`)
        .then((res) => {
          const data = res.data;
          if (data.success) {
            this.payments = data.result || [];
            this.pagination = data.pagination || this.pagination;
            this.totals = data.totals || this.totals;
          } else {
            this.payments = [];
            this.resetPagination();
          }
          this.loadingData = false;
        })
        .catch((err) => {
          console.error("Erro ao buscar pagamentos:", err);
          this.showToast("Erro!", "danger", "Erro ao carregar pagamentos.");
          this.payments = [];
          this.resetPagination();
          this.loadingData = false;
        });
    },

    resetPagination() {
      this.pagination = {
        currentPage: 1,
        totalPages: 1,
        totalItems: 0,
        itemsPerPage: this.perPage,
        hasNextPage: false,
        hasPrevPage: false,
      };
      this.totals = { totalAmount: 0 };
    },

    onPageChange(page) {
      this.fetchPayments(page);
    },

    clearFilters() {
      this.fromDate = moment().startOf("month").format("YYYY-MM-DD");
      this.toDate = moment().format("YYYY-MM-DD");
      this.searchTerm = "";
      this.selectedPaymentMethod = 0;
      this.fetchPayments(1);
    },

    // ==================== FORMATAÇÃO ====================

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    getCustomerName(accountNumber) {
      const customer = this.customers.find((c) => c.accountNumber == accountNumber);
      return customer ? customer.customerName : "N/A";
    },

    getPaymentMethod(method) {
      const methods = {
        1: "Boca do Caixa",
        2: "Depósito Bancário",
        3: "Transferência Bancária",
        4: "POS",
        5: "Cheque",
        6: "SISTAFE",
        7: "M-Pesa",
        8: "E-Mola",
      };
      return methods[method] || "Outro";
    },

    getMethodVariant(method) {
      const variants = {
        1: "success",
        2: "primary",
        3: "info",
        4: "secondary",
        5: "warning",
        6: "dark",
        7: "danger",
        8: "success",
      };
      return variants[method] || "secondary";
    },

    getPeriodLabel() {
      if (!this.fromDate || !this.toDate) return "";
      return moment(this.fromDate).format("DD/MM/YYYY") + " a " + moment(this.toDate).format("DD/MM/YYYY");
    },

    getRowIndex(idx) {
      return (this.pagination.currentPage - 1) * this.perPage + idx + 1;
    },

    getShowingFrom() {
      return (this.pagination.currentPage - 1) * this.perPage + 1;
    },

    getShowingTo() {
      const to = this.pagination.currentPage * this.perPage;
      return to > this.pagination.totalItems ? this.pagination.totalItems : to;
    },

    // ==================== TOTAIS DA PÁGINA ====================

    getPageTotalAmount() {
      return this.payments.reduce((sum, p) => sum + (p.amount || 0), 0);
    },

    // ==================== EXPORTAR EXCEL ====================

    async exportExcel() {
      this.showToast("A exportar...", "info", "A preparar ficheiro Excel.");

      try {
        const allPayments = await this.fetchAllPayments();

        const DATA_ROWS = allPayments.map((row, i) => ({
          "#": i + 1,
          "Nome do Cliente": this.getCustomerName(row.accountNumber),
          "Nº Conta": row.accountNumber,
          "Valor Pago (MZN)": row.amount || 0,
          "Método de Pagamento": this.getPaymentMethod(row.paymentMethod),
          "Referência": row.tranzactionReference,
          "Data de Pagamento": DateFormat.formatDate(row.paymentDate || row.createdAt),
          "Técnico": row.staffName,
          "Descrição": row.description,
        }));

        // Add totals row
        DATA_ROWS.push({});
        DATA_ROWS.push({
          "#": "",
          "Nome do Cliente": "",
          "Nº Conta": "TOTAL",
          "Valor Pago (MZN)": this.totals.totalAmount,
          "Método de Pagamento": "",
          "Referência": "",
          "Data de Pagamento": "",
          "Técnico": "",
          "Descrição": "",
        });

        const workSheet = XLSX.utils.json_to_sheet(DATA_ROWS);

        workSheet["!cols"] = [
          { wch: 6 },
          { wch: 28 },
          { wch: 12 },
          { wch: 18 },
          { wch: 22 },
          { wch: 20 },
          { wch: 18 },
          { wch: 20 },
          { wch: 25 },
        ];

        const workBook = XLSX.utils.book_new();
        const rangeLabel = `${this.fromDate}_a_${this.toDate}`;
        XLSX.utils.book_append_sheet(workBook, workSheet, "Pagamentos");
        XLSX.writeFile(workBook, `Pagamentos_Prestacoes_${rangeLabel}.xlsx`);

        this.showToast("Sucesso", "success", "Ficheiro Excel exportado com sucesso.");
      } catch (err) {
        console.error("Erro ao exportar Excel:", err);
        this.showToast("Erro!", "danger", "Erro ao exportar ficheiro Excel.");
      }
    },

    // ==================== EXPORTAR PDF ====================

    async exportPDF() {
      this.showToast("A exportar...", "info", "A preparar ficheiro PDF.");

      try {
        const allPayments = await this.fetchAllPayments();

        const body = allPayments.map((row, i) => [
          { text: i + 1, fontSize: 7, alignment: "center" },
          { text: this.getCustomerName(row.accountNumber), fontSize: 7 },
          { text: row.accountNumber, fontSize: 7, alignment: "center" },
          { text: MoneyFormat.formatMoney(row.amount), fontSize: 7, alignment: "right" },
          { text: this.getPaymentMethod(row.paymentMethod), fontSize: 7, alignment: "center" },
          { text: row.tranzactionReference || "", fontSize: 7, alignment: "center" },
          { text: DateFormat.formatDate(row.paymentDate || row.createdAt), fontSize: 7, alignment: "center" },
          { text: row.staffName || "", fontSize: 7 },
        ]);

        // Totals row
        body.push([
          { text: "", fontSize: 7 },
          { text: "", fontSize: 7 },
          { text: "TOTAL", fontSize: 7, bold: true, alignment: "right" },
          { text: MoneyFormat.formatMoney(this.totals.totalAmount), fontSize: 7, bold: true, alignment: "right", fillColor: "#d4edda" },
          { text: "", fontSize: 7 },
          { text: "", fontSize: 7 },
          { text: "", fontSize: 7 },
          { text: "", fontSize: 7 },
        ]);

        const docDefinition = {
          pageOrientation: "landscape",
          pageMargins: [20, 60, 20, 40],
          header: {
            columns: [
              {
                text: this.company.companyName || "Microcrédito",
                fontSize: 11,
                bold: true,
                margin: [20, 15, 0, 0],
                color: "#009640",
              },
              {
                text: `Pagamentos de Prestações\n${this.getPeriodLabel()}`,
                fontSize: 9,
                alignment: "right",
                margin: [0, 15, 20, 0],
                color: "#333333",
              },
            ],
          },
          content: [
            {
              table: {
                headerRows: 1,
                widths: ["auto", "*", "auto", "auto", "auto", "auto", "auto", "auto"],
                body: [
                  [
                    { text: "#", style: "columnsTitle" },
                    { text: "Nome do Cliente", style: "columnsTitle" },
                    { text: "Nº Conta", style: "columnsTitle" },
                    { text: "Valor Pago", style: "columnsTitle" },
                    { text: "Método", style: "columnsTitle" },
                    { text: "Referência", style: "columnsTitle" },
                    { text: "Data", style: "columnsTitle" },
                    { text: "Técnico", style: "columnsTitle" },
                  ],
                  ...body,
                ],
              },
              layout: {
                hLineWidth: function () { return 0.5; },
                vLineWidth: function () { return 0.5; },
                hLineColor: function () { return "#cccccc"; },
                vLineColor: function () { return "#cccccc"; },
                fillColor: function (rowIndex) {
                  if (rowIndex === 0) return "#009640";
                  return rowIndex % 2 === 0 ? "#f8f9fa" : null;
                },
              },
            },
            { text: "\n" },
            {
              columns: [
                {
                  text: `Total de registos: ${allPayments.length}`,
                  fontSize: 8,
                  color: "#666",
                },
                {
                  text: `Gerado em: ${moment().format("DD/MM/YYYY HH:mm")}`,
                  fontSize: 8,
                  color: "#666",
                  alignment: "right",
                },
              ],
            },
          ],
          styles: {
            columnsTitle: {
              fontSize: 7,
              bold: true,
              color: "#ffffff",
              alignment: "center",
            },
          },
          footer: function (currentPage, pageCount) {
            return {
              columns: [
                {
                  text: `Página ${currentPage} de ${pageCount}`,
                  alignment: "center",
                  fontSize: 7,
                  margin: [0, 10, 0, 0],
                  color: "#999",
                },
              ],
            };
          },
        };

        pdfMake.createPdf(docDefinition).open();
        this.showToast("Sucesso", "success", "PDF gerado com sucesso.");
      } catch (err) {
        console.error("Erro ao exportar PDF:", err);
        this.showToast("Erro!", "danger", "Erro ao gerar PDF.");
      }
    },

    // ==================== FETCH ALL (para exportação) ====================

    async fetchAllPayments() {
      const params = new URLSearchParams();
      params.append("page", "1");
      params.append("limit", "10000");

      if (this.fromDate) params.append("fromDate", this.fromDate);
      if (this.toDate) params.append("toDate", this.toDate);
      if (this.searchTerm) params.append("search", this.searchTerm);
      if (this.selectedPaymentMethod > 0) {
        params.append("paymentMethod", this.selectedPaymentMethod);
      }

      const res = await axios.get(
        `/api/payments/${this.company.id}/paginated?${params.toString()}`
      );

      if (res.data.success) {
        return res.data.result || [];
      }
      return [];
    },

    // ==================== UTILITÁRIOS ====================

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 3000,
      });
    },
  },
};
</script>

